#!/usr/bin/env python3
# Generated by Claude Opus 5 (Anthropic)
"""Crop a screenshot to the aspect of one Figure-1 panel.

The model figure is one Miro frame of 2x2 quadrants exported at ~2.433:1, so a
full quadrant is 2.433:1 and a quadrant split horizontally in two is 4.866:1.
This crops (never stretches) to that aspect, keeping as much of the image as
possible, and says what it threw away.

usage:
  fit_panel.py shot.png                      # full quadrant, centred
  fit_panel.py shot.png --half               # half quadrant (4.866:1)
  fit_panel.py shot.png --anchor top         # keep the top instead of centring
  fit_panel.py shot.png --aspect 3.0 -o out.png
"""
import argparse, os
from PIL import Image

QUADRANT, HALF = 2.433, 4.866

ap = argparse.ArgumentParser()
ap.add_argument("image")
ap.add_argument("-o", "--out")
ap.add_argument("--aspect", type=float)
ap.add_argument("--half", action="store_true", help="4.866:1 instead of 2.433:1")
ap.add_argument("--anchor", default="center",
                choices=["center", "top", "bottom", "left", "right"])
a = ap.parse_args()
target = a.aspect or (HALF if a.half else QUADRANT)

im = Image.open(a.image)
w, h = im.size
if w / h > target:                       # too wide -> trim width
    nw, nh = int(round(h * target)), h
else:                                    # too tall -> trim height
    nw, nh = w, int(round(w / target))
if a.anchor in ("center", "top", "bottom"):
    x = (w - nw) // 2
else:
    x = 0 if a.anchor == "left" else w - nw
if a.anchor == "top":
    y = 0
elif a.anchor == "bottom":
    y = h - nh
else:
    y = (h - nh) // 2

out = a.out or os.path.splitext(a.image)[0] + f"_panel{'_half' if a.half else ''}.png"
im.crop((x, y, x + nw, y + nh)).save(out)
lost = 100 * (1 - (nw * nh) / (w * h))
print(f"{w}x{h} ({w/h:.3f})  ->  {nw}x{nh} ({nw/nh:.3f})  target {target}  "
      f"dropped {lost:.1f}%  anchor={a.anchor}")
print(out)
